/**
 * Unit tests for model-switch-consent (PreModelSwitch, CC 2.1.251, #3789).
 * The fixture payloads are the ones captured from a real 2.1.251 session on
 * 2026-08-29 with a stdin-dumping hook, field for field.
 */

import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { mockCommonBasic } from '../fixtures/mock-common.js';

vi.mock('../../lib/common.js', () => mockCommonBasic({}));

import { modelSwitchConsent, WARM_CONTEXT_WARN_TOKENS } from '../../lifecycle/model-switch-consent.js';
import type { HookInput } from '../../types.js';

/** Verbatim shape of the 2.1.251 PreModelSwitch payload (paths elided). */
function payload(overrides: Record<string, unknown> = {}): HookInput {
  return {
    session_id: 'bc4be102-5954-4d73-9407-b3d40f785627',
    transcript_path: '/tmp/t.jsonl',
    cwd: '/tmp/hookdump',
    prompt_id: '58e08989-5d21-42da-befd-6762aef60a56',
    hook_event_name: 'PreModelSwitch',
    from_model: 'claude-sonnet-5',
    to_model: 'claude-opus-5',
    requested_model: 'claude-opus-5',
    source: 'command',
    context_tokens: 0,
    prompt_cache_warm: false,
    cache_ttl: '1h',
    estimated_cache_write_usd: 0,
    pricing: 'catalog',
    ...overrides,
  } as unknown as HookInput;
}

describe('model-switch-consent (PreModelSwitch)', () => {
  const env = { ...process.env };
  beforeEach(() => { delete process.env.ORK_FABLE_OK; });
  afterEach(() => { process.env = { ...env }; });

  test('a switch onto a non-premium model passes silently', () => {
    const r = modelSwitchConsent(payload());
    expect(r.continue).toBe(true);
    expect(r.hookSpecificOutput).toBeUndefined();
  });

  test('a switch onto Fable asks, on the PreModelSwitch event, with a reason that names both models', () => {
    const r = modelSwitchConsent(payload({ to_model: 'claude-fable-5', requested_model: 'claude-fable-5' }));
    expect(r.continue).toBe(true);
    expect(r.hookSpecificOutput?.hookEventName).toBe('PreModelSwitch');
    expect(r.hookSpecificOutput?.permissionDecision).toBe('ask');
    const reason = r.hookSpecificOutput?.permissionDecisionReason ?? '';
    expect(reason).toContain('claude-sonnet-5');
    expect(reason).toContain('claude-fable-5');
    expect(reason).toContain('ORK_FABLE_OK=1');
  });

  test('the measured re-cache cost is quoted when CC supplies one', () => {
    const r = modelSwitchConsent(payload({
      to_model: 'claude-fable-5', requested_model: 'claude-fable-5',
      context_tokens: 123705, prompt_cache_warm: true, estimated_cache_write_usd: 0.4948,
    }));
    const reason = r.hookSpecificOutput?.permissionDecisionReason ?? '';
    expect(reason).toContain('$0.49');
    expect(reason).toContain('123,705');
    expect(reason).toContain('catalog');
  });

  test('a zero re-cache cost is not quoted', () => {
    const r = modelSwitchConsent(payload({ to_model: 'claude-fable-5', requested_model: 'claude-fable-5' }));
    expect(r.hookSpecificOutput?.permissionDecisionReason ?? '').not.toContain('Re-caching');
  });

  test('short ids, the 1M suffix and the Mythos family are all premium', () => {
    for (const to of ['fable', 'claude-fable-5[1m]', 'mythos', 'claude-mythos-5']) {
      const r = modelSwitchConsent(payload({ to_model: to, requested_model: to }));
      expect(r.hookSpecificOutput?.permissionDecision, to).toBe('ask');
    }
  });

  test('moving within the premium tier does not re-ask', () => {
    const r = modelSwitchConsent(payload({ from_model: 'claude-fable-5', to_model: 'claude-fable-5[1m]', requested_model: 'claude-fable-5[1m]' }));
    expect(r.hookSpecificOutput).toBeUndefined();
  });

  test('ORK_FABLE_OK=1 pre-consents, exactly like the spawn gate', () => {
    process.env.ORK_FABLE_OK = '1';
    const r = modelSwitchConsent(payload({ to_model: 'claude-fable-5', requested_model: 'claude-fable-5' }));
    expect(r.hookSpecificOutput).toBeUndefined();
  });

  test('a payload without to_model is a silent no-op, never a throw', () => {
    const r = modelSwitchConsent({ hook_event_name: 'PreModelSwitch', session_id: 's' } as unknown as HookInput);
    expect(r.continue).toBe(true);
    expect(r.hookSpecificOutput).toBeUndefined();
  });
});

describe('model-switch-consent: warm large-context re-cache warning', () => {
  const env = { ...process.env };
  beforeEach(() => { delete process.env.ORK_FABLE_OK; });
  afterEach(() => { process.env = { ...env }; });

  const warmLarge = {
    context_tokens: WARM_CONTEXT_WARN_TOKENS + 23705,
    prompt_cache_warm: true,
    estimated_cache_write_usd: 5.8125,
  };

  test('a warm context above the threshold gets one warning line naming the cost and the alternative', () => {
    const r = modelSwitchConsent(payload(warmLarge));
    expect(r.continue).toBe(true);
    expect(r.hookSpecificOutput).toBeUndefined();
    const msg = r.systemMessage ?? '';
    expect(msg).not.toContain('\n');
    expect(msg).toContain('claude-sonnet-5');
    expect(msg).toContain('claude-opus-5');
    expect(msg).toContain('123,705');
    expect(msg).toContain('$5.81');
    expect(msg).toContain('subagent');
    expect(msg).toContain('fresh session');
  });

  test('the warning never blocks or asks', () => {
    const r = modelSwitchConsent(payload(warmLarge));
    expect(r.continue).toBe(true);
    expect(r.hookSpecificOutput?.permissionDecision).toBeUndefined();
  });

  test('without a cost estimate the warning still fires, without a dollar figure', () => {
    const r = modelSwitchConsent(payload({ ...warmLarge, estimated_cache_write_usd: 0 }));
    expect(r.systemMessage ?? '').toContain('123,705');
    expect(r.systemMessage ?? '').not.toContain('$');
  });

  test('a cold cache is silent even on a large context', () => {
    const r = modelSwitchConsent(payload({ ...warmLarge, prompt_cache_warm: false }));
    expect(r.systemMessage).toBeUndefined();
  });

  test('a warm cache at or below the threshold is silent', () => {
    const r = modelSwitchConsent(payload({ ...warmLarge, context_tokens: WARM_CONTEXT_WARN_TOKENS }));
    expect(r.systemMessage).toBeUndefined();
  });

  test('a premium-tier ask keeps its own reason and adds no second warning', () => {
    const r = modelSwitchConsent(payload({ ...warmLarge, to_model: 'claude-fable-5', requested_model: 'claude-fable-5' }));
    expect(r.hookSpecificOutput?.permissionDecision).toBe('ask');
    expect(r.systemMessage).toBeUndefined();
  });

  test('a pre-consented premium switch on a warm large context still warns', () => {
    process.env.ORK_FABLE_OK = '1';
    const r = modelSwitchConsent(payload({ ...warmLarge, to_model: 'claude-fable-5', requested_model: 'claude-fable-5' }));
    expect(r.hookSpecificOutput).toBeUndefined();
    expect(r.systemMessage ?? '').toContain('claude-fable-5');
  });
});
